// Pseudo Azure Function for Event Hub trigger
module.exports = async function(context, eventHubMessages) {
  const { CosmosClient } = require('@azure/cosmos');
  const client = new CosmosClient(process.env.COSMOS_CONNECTION_STRING);
  const container = client.database("Telemetry").container("PerTenantAggregates");
  for (const m of eventHubMessages) {
    const payload = JSON.parse(m.body);
    const tenantId = payload.tenantId;
    await container.items.upsert({ id: tenantId, ...payload.aggregate });
  }
}
```

